import{_ as t,o,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Products — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Products — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/products"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Products — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/products"}]]},"headers":[],"relativePath":"user-guide/products.md","filePath":"user-guide/products.md","lastUpdated":1786218247000}'),s={name:"user-guide/products.md"};function n(c,e,d,i,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="products-—-user-guide" tabindex="-1">Products — User Guide <a class="header-anchor" href="#products-—-user-guide" aria-label="Permalink to &quot;Products — User Guide&quot;">​</a></h1><h2 id="who-can-use-products" tabindex="-1">Who can use Products <a class="header-anchor" href="#who-can-use-products" aria-label="Permalink to &quot;Who can use Products&quot;">​</a></h2><p>Your workspace needs the free <strong>Products</strong> module. Access is controlled by <code>products.view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, and <code>force.delete</code>.</p><h2 id="products-list" tabindex="-1">Products list <a class="header-anchor" href="#products-list" aria-label="Permalink to &quot;Products list&quot;">​</a></h2><p>Open <strong>Products</strong> from the <strong>Inventory</strong> sidebar group. Search by SKU or name, filter by category and status, and use the KPI cards to focus the list. Users with restore permission can include deleted products or show deleted products only.</p><h2 id="create-and-edit-a-product-or-service" tabindex="-1">Create and edit a product or service <a class="header-anchor" href="#create-and-edit-a-product-or-service" aria-label="Permalink to &quot;Create and edit a product or service&quot;">​</a></h2><p>The Products catalog covers both <strong>goods</strong> and <strong>services</strong>. Use one record type for everything you sell or purchase.</p><ol><li>Select <strong>New product</strong>.</li><li>Enter a unique SKU and a name.</li><li>Optionally choose a category and add description, unit, cost, price, and reorder level.</li><li>Choose a <strong>currency</strong> from the shared workspace currency list (defaults to your workspace currency from Settings).</li><li>Keep <strong>Track stock</strong> enabled for goods whose quantities should be managed by Inventory. Turn <strong>Track stock</strong> off for services and other non-stocked items.</li><li>Save.</li></ol><p>Products can be Active or Inactive. Inactive products remain in the catalog but should not be used for new operational work.</p><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>Manage categories from the product category action. A category has a name and optional description. Categories use the same Products permissions; removing a category does not remove its products.</p><h2 id="notes-activity-and-deletion" tabindex="-1">Notes, activity, and deletion <a class="header-anchor" href="#notes-activity-and-deletion" aria-label="Permalink to &quot;Notes, activity, and deletion&quot;">​</a></h2><p>The detail sheet contains:</p><ul><li><strong>Notes</strong> for free-form product context</li><li><strong>Activity</strong> for create, update, note, delete, and restore events</li></ul><p>Delete is a soft delete. Restore requires <code>products.restore</code>; permanent deletion requires <code>products.force.delete</code> and the product must already be deleted.</p><h2 id="inventory-and-purchasing" tabindex="-1">Inventory and purchasing <a class="header-anchor" href="#inventory-and-purchasing" aria-label="Permalink to &quot;Inventory and purchasing&quot;">​</a></h2><p>Only products with <strong>Track stock</strong> enabled can receive stock adjustments, Purchase Order receipts, or transfers. Product selection on Purchase Order lines is optional; ordinary description-only lines still work.</p>',17)])])}const g=t(s,[["render",n]]);export{h as __pageData,g as default};
